from __future__ import absolute_import
from taf.selenium.sbts.pages import v22r1


class RndMode(v22r1.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._fiveg_performance_test = NrPerformanceTestPage(driver)


class NrPerformanceTestPage(v22r1.rnd_mode.NrPerformanceTestPage):
    def __init__(self, driver):
        super(NrPerformanceTestPage, self).__init__(driver)
        self._view_panel = NrPerformanceTestPageViewPanel(driver)


class NrPerformanceTestPageViewPanel(v22r1.rnd_mode.NrPerformanceTestPageViewPanel):
    def __init__(self, driver):
        super(NrPerformanceTestPageViewPanel, self).__init__(driver)
